const app=document.querySelector('#app'),toast=document.querySelector('#toast'),logout=document.querySelector('#logout');
let current=null,overview=null,invite=null,mode='login',timer=null;
const money=n=>(Number(n)||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const date=s=>new Date(s+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'long',year:'numeric'});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function flash(s){toast.textContent=s;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),3200)}
async function api(path,options={}){const r=await fetch('/api/finance'+path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(options.headers||{})},...options});const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||'Não foi possível concluir.');return data}
function authView(){logout.hidden=true;app.innerHTML=`<section class="auth-shell"><div class="auth-copy"><span class="eyebrow">CONTROLE FAMILIAR · ORGANIZAÇÃO FINANCEIRA</span><h1>Dinheiro em<br><em>ordem.</em></h1><p>Um espaço privado para acompanhar contribuições, confirmar pagamentos e deixar os vencimentos organizados. Cada pessoa vê somente o que pertence ao seu acesso.</p><div class="notice">Acesso familiar individual. Se você administra o controle, entre primeiro no <a href="/painel/" style="color:#ff9a32">painel administrativo</a> da área administrativa e depois volte para esta página.</div></div><div class="auth-card"><h2>${mode==='login'?'Acessar minha conta':'Criar meu acesso'}</h2><p>${mode==='login'?'Entre com o e-mail e a senha cadastrados.':'O cadastro exige um convite individual fornecido pelo administrador.'}</p><form id="auth-form">${mode==='register'?'<div class="field"><label>SEU NOME</label><input name="name" autocomplete="name" required minlength="2"></div><div class="field"><label>CÓDIGO DE CONVITE</label><input name="code" autocomplete="one-time-code" required></div>':''}<div class="field"><label>E-MAIL</label><input name="email" type="email" autocomplete="email" required></div><div class="field"><label>SENHA ${mode==='register'?'(MÍNIMO 10 CARACTERES)':''}</label><input name="password" type="password" autocomplete="${mode==='login'?'current-password':'new-password'}" required minlength="${mode==='register'?10:1}"></div><button type="submit">${mode==='login'?'Entrar com segurança':'Criar minha conta'}</button></form><div class="switch">${mode==='login'?'Recebeu um convite?':'Já tem uma conta?'} <button id="switch-mode">${mode==='login'?'Criar acesso':'Fazer login'}</button></div></div></section>`;
document.querySelector('#switch-mode').onclick=()=>{mode=mode==='login'?'register':'login';authView()};
document.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));try{const x=await api(mode==='login'?'/login':'/register',{method:'POST',body:JSON.stringify(b)});current=x.user;await load();}catch(err){flash(err.message)}};
}
function status(x){const s=x.status;return '<span class="status '+s+'">'+({pending:'Pendente',reported:'Informado · aguardando conferência',confirmed:'Confirmado',overdue:'Em atraso'}[s]||s)+'</span>'}
function render(){
 const u=overview.user,admin=u.role==='admin',items=overview.items,summary=overview.summary;
 logout.hidden=false;
 app.innerHTML=`<section class="hero"><div><span class="eyebrow">ÁREA ${admin?'ADMINISTRATIVA':'FAMILIAR'} · FINANCEIRO 2026—2027</span><h1>${admin?'Visão geral.':'Olá, '+esc(u.name.split(' ')[0])+'.'}</h1><p>${admin?'Acompanhe as contribuições previstas, confira pagamentos informados e mantenha o planejamento atualizado.':'Aqui você acompanha somente suas contribuições, os vencimentos e o histórico de confirmações.'}</p></div><div class="hero-date">PLANEJAMENTO ATIVO<strong>Nov 2026 — Mar 2027</strong></div></section>
 <section class="grid"><article class="metric"><small>Total previsto</small><strong>${money(summary.expected)}</strong><span>Contribuições cadastradas</span></article><article class="metric primary"><small>Confirmado</small><strong>${money(summary.confirmed)}</strong><span>Recebimentos validados</span></article><article class="metric"><small>Em aberto</small><strong>${money(summary.pending)}</strong><span>Inclui valores informados</span></article><article class="metric"><small>Progresso</small><strong>${summary.progress}%</strong><div class="progress"><span style="width:${summary.progress}%"></span></div></article></section>
 <div class="section-head"><div><h2>${admin?'Contribuições da família':'Suas contribuições'}</h2><p>Vencimentos, status e valores registrados.</p></div><span class="eyebrow">${items.length} LANÇAMENTOS</span></div>
 <section class="table-wrap">${items.length?items.map((x,i)=>`<article class="payment" style="animation-delay:${i*45}ms"><div><strong>${esc(x.label)}</strong><small>${x.person_role==='father'?'Pai':'Mãe'} · Vencimento ${date(x.due_date)}</small></div><div class="amount">${money(x.amount)}</div><div class="pay-meta">${status(x)}</div><div class="actions">${admin?(x.status!=='confirmed'?'<button class="tiny confirm" data-id="'+x.id+'">Confirmar</button>':'<span class="muted" style="font-size:10px">Validado</span>'):(x.status==='pending'||x.status==='overdue'?'<button class="tiny report" data-id="'+x.id+'">Informar pagamento</button>':x.status==='reported'?'<span class="muted" style="font-size:10px">Aguardando validação</span>':'<span class="muted" style="font-size:10px">Concluído</span>')}</div></article>`).join(''):'<div class="empty">Nenhuma contribuição cadastrada.</div>'}</section>
 ${admin?'<section class="card" style="margin-top:24px"><div class="section-head" style="margin-top:0"><div><h2>Acessos dos familiares</h2><p>Crie convites individuais para seu pai e sua mãe.</p></div></div><div class="actions" style="justify-content:flex-start"><button id="invite-father" class="quiet">＋ Convite para o pai</button><button id="invite-mother" class="quiet">＋ Convite para a mãe</button></div><div id="invite-result">'+(invite?'<div class="invite-card"><div><span class="eyebrow">CONVITE · '+(invite.role==='father'?'PAI':'MÃE')+'</span><p>Compartilhe este código em particular. Ele expira em 7 dias e só pode ser usado uma vez.</p><div class="invite-code">'+esc(invite.code)+'</div></div><button id="copy-invite">Copiar código</button></div>':'')+'</div></section><section class="card" style="margin-top:18px"><div class="eyebrow">REGRAS INICIAIS</div><p style="font-size:12px;color:var(--muted);line-height:1.8;margin-bottom:0">Pai: R$ 800 no fim de cada mês de novembro/2026 a março/2027, mais R$ 3.000 em dezembro. Mãe: R$ 4.000 em março/2027. A confirmação do familiar não valida o recebimento automaticamente.</p></section>':''}
 <section class="section-head"><div><h2>Central de avisos</h2><p>Alertas de vencimento e atualizações da conta.</p></div><button class="quiet tiny" id="enable-notifications">Ativar avisos neste aparelho</button></section><div id="notifications" class="card"><div class="empty">Carregando avisos…</div></div>`;
 document.querySelectorAll('.report').forEach(b=>b.onclick=async()=>{const note=prompt('Se desejar, informe uma observação ou referência do pagamento:')||'';try{await api('/contributions/'+b.dataset.id+'/report',{method:'POST',body:JSON.stringify({note})});flash('Pagamento informado. Ele aparecerá para conferência.');await load()}catch(e){flash(e.message)}});
 document.querySelectorAll('.confirm').forEach(b=>b.onclick=async()=>{if(!confirm('Confirmar que este valor foi recebido?'))return;try{await api('/contributions/'+b.dataset.id+'/confirm',{method:'POST',body:JSON.stringify({})});flash('Recebimento confirmado.');await load()}catch(e){flash(e.message)}});
 if(admin){document.querySelector('#invite-father').onclick=()=>makeInvite('father');document.querySelector('#invite-mother').onclick=()=>makeInvite('mother');const cp=document.querySelector('#copy-invite');if(cp)cp.onclick=()=>navigator.clipboard.writeText(invite.code).then(()=>flash('Código copiado.')).catch(()=>flash('Não foi possível copiar automaticamente.'))}
 document.querySelector('#enable-notifications').onclick=async()=>{if(!('Notification'in window)){flash('Este navegador não oferece notificações.');return}const p=await Notification.requestPermission();flash(p==='granted'?'Avisos ativados neste aparelho enquanto o painel estiver aberto.':'Permissão de notificação não concedida.')};
 loadNotifications();
}
async function makeInvite(role){try{invite=await api('/invites',{method:'POST',body:JSON.stringify({role})});render();flash('Convite criado. Compartilhe em particular.')}catch(e){flash(e.message)}}
async function loadNotifications(){const el=document.querySelector('#notifications');if(!el)return;try{const x=await api('/notifications');el.innerHTML=x.items.length?x.items.map(n=>'<div style="padding:12px 2px;border-bottom:1px solid #ffffff12"><strong style="font-size:12px">'+esc(n.title)+'</strong><p style="font-size:11px;color:var(--muted);margin:6px 0 0">'+esc(n.message)+'</p></div>').join(''):'<div class="empty">Nenhum aviso por enquanto. Os próximos vencimentos aparecerão aqui.</div>';if(Notification.permission==='granted'){const newest=x.items.find(n=>!n.sent_at);if(newest&&!sessionStorage.getItem('ffnotice-'+newest.id)){new Notification(newest.title,{body:newest.message,tag:newest.id});sessionStorage.setItem('ffnotice-'+newest.id,'1')}}}catch{}}
async function load(){try{overview=await api('/overview');current=overview.user;render();if(timer)clearInterval(timer);timer=setInterval(()=>{loadNotifications();api('/overview').then(x=>{overview=x;render()}).catch(()=>{})},45000)}catch(e){if(e.message.includes('Entre'))authView();else app.innerHTML='<div class="card"><h2>Não foi possível carregar</h2><p class="muted">'+esc(e.message)+'</p><button onclick="location.reload()">Tentar novamente</button></div>'}}
logout.onclick=async()=>{try{await api('/logout',{method:'POST',body:'{}'})}catch{}current=null;overview=null;invite=null;mode='login';if(timer)clearInterval(timer);authView()};
(async()=>{try{const s=await api('/session');if(s.user?.role==='admin'){current=s.user;await load()}else if(s.user){current=s.user;await load()}else authView()}catch{authView()}})();
